head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
    textbox1.setValue("main_bigDecimal_test");
    var str = 'scwin.a = scwin.$w.bigDecimal("1");\nscwin.b= scwin.$w.bigDecimal("2");\nscwin.$w.bigDecimal.calc("scwin.a + scwin.b")=?';
    textarea1.setValue(str);
}
scwin.trigger1_onclick = function() {
    scwin.a = scwin.$w.bigDecimal("1");
    scwin.b = scwin.$w.bigDecimal("2");
    input1.setValue(scwin.$w.bigDecimal.calc("scwin.a + scwin.b").toString());
}
scwin.checkValue = function(id, value) {
    if (scwin.__getDom($p.id + id).value == value) {
        return true;
    }
    return false
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("externalJS/big/big.min.js");
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
}
